'use client';

import { Transition } from '@headlessui/react';
import {
  ChatBubbleOvalLeftEllipsisIcon, CheckIcon, ChevronLeftIcon,
  ChevronRightIcon, CodeBracketIcon, QuestionMarkCircleIcon,
} from '@heroicons/react/20/solid';
import { LinkIcon } from '@heroicons/react/24/solid';
import { useQueryClient } from '@tanstack/react-query';
import { getQueryKey } from '@trpc/react-query';
import classNames from 'classnames';
import { useSession } from 'next-auth/react';
import dynamic from 'next/dynamic';
import { useRouter } from 'next/navigation';
import {
  memo, useCallback, useEffect, useMemo, useRef, useState,
} from 'react';
import { useLabel } from 'react-aria';

import MessagePreview from '../../../components/MessagePreview';

import type { ContentLossOption } from '~/utils';

import WebhookIcon from '~/assets/svg/WebhookIcon';
import Button from '~/components/Button';
import Dropdown from '~/components/Dropdown';
import Form from '~/components/Form';
import LoadingDots from '~/components/LoadingDots';
import NullableComponent from '~/components/NullableComponent';
import PresetDialog, { DialogFooter } from '~/components/PresetDialog';
import StyledAccordion from '~/components/StyledAccordion';
import TextField from '~/components/TextField';
import TransitionHeightElement from '~/components/TransitionHeightElement';
import { DISCORD_MESSAGE_LINK_REGEX, MAX_MESSAGE_NAME_LENGTH } from '~/constants';
import { describeDroppedComponentTypesNotice } from '~/server/api/utils/shapes';
import styles from '~/styles';
import {
  applyDisposition, describeDropSet, formatMutationError, gateBeforePersist, makeEditable,
  noticeMessageForSettled, resolveContentLoss, saveAsPayload, validateContentRequirements,
} from '~/utils';
import { api } from '~/utils/api';
import useGuildDropdownItems from '~/utils/hooks/useGuildDropdownItems';
import useValidateWebhook from '~/utils/hooks/useValidateWebhook';

const NewMessageJsonInput = dynamic(() => import('./NewMessageJsonInput'), { ssr: false });

// const FEATURES = [
//   // 'Save messages for other server admins to see.',
//   'Load any message directly from your server.',
//   'Access your server\'s emojis directly from the editor.',
//   'See all webhooks in your server and send messages with them.',
// ];

type LoadOption = 'bot' | 'webhook' | 'code' | 'json';

type Props = {
  open: boolean;
  onClose: VoidFunction;
  guildId?: string;
};

const NewMessageModal: FC<Props> = (props) => {
  const { open, onClose, guildId = '' } = props;
  const { data: session } = useSession();
  const router = useRouter();

  const [messageIdOrUrl, setMessageLink] = useState('');
  const [commandMessageCode, setCommandMessageCode] = useState('');
  const [webhookUrl, setWebhookUrl] = useState('');
  const [page, setPage] = useState<0 | 1>(0);
  const [loadOption, setLoadOption] = useState<LoadOption>(session ? 'bot' : 'webhook');
  const [jsonMessage, setJsonMessage] = useState<null | MessageData>(null);
  const [messageName, setMessageName] = useState('');
  const [selectedGuildId, setSelectedGuildId] = useState(guildId ?? '0');
  const {
    mutate: upsertMessage, isPending: isSavingMessage, error: messageError,
  } = api.message.upsert.useMutation({
    onSuccess: ({ id }) => router.push(`/message/m/${id}/edit`),
  });
  const {
    isLoading: isLoadingWebhook, message: webhookMessage, webhook,
    droppedComponentTypes: webhookDroppedComponentTypes,
    messageError: webhookMessageError, webhookError,
  } = useValidateWebhook(webhookUrl, messageIdOrUrl);

  const {
    data: discordMessage, isFetching: isFetchingDiscordMessage,
    error: discordMessageError,
  } = api.message.getFromUrl.useQuery({ url: messageIdOrUrl }, {
    enabled: loadOption === 'bot' && DISCORD_MESSAGE_LINK_REGEX.test(messageIdOrUrl) && !webhook && !!session,
    refetchOnWindowFocus: false,
    refetchOnMount: false,
    retry: false,
  });
  const {
    data: commandMessage, isFetching: isFetchingCommandMessage,
    error: commandMessageError,
  } = api.message.getFromCode.useQuery({ code: commandMessageCode }, {
    enabled: loadOption === 'code' && commandMessageCode.length > 1,
    refetchOnWindowFocus: false,
    refetchOnMount: false,
    retry: false,
  });

  useEffect(() => {
    const gId = webhook?.guild_id ?? discordMessage?.guildId ?? commandMessage?.guildId ?? null;
    if (!guildId && gId) setSelectedGuildId(gId);
  }, [webhook, discordMessage, commandMessage]);

  const loadedMessage = useMemo(() => {
    const tmp = discordMessage?.message
    ?? webhookMessage
    ?? commandMessage?.data
    ?? jsonMessage;
    if (!tmp) return undefined;

    return makeEditable({ data: tmp }).data;
  }, [
    discordMessage?.message,
    webhookMessage,
    commandMessage?.data,
    jsonMessage,
  ]);
  const droppedComponentTypes = discordMessage?.droppedComponentTypes
    ?? webhookDroppedComponentTypes ?? [];
  const { settledMessage, settledNotice } = useMemo(() => {
    if (!loadedMessage) return { settledMessage: undefined, settledNotice: null };
    const disposition = resolveContentLoss(
      loadedMessage.flags as number | undefined,
      loadedMessage.components as undefined | { type: number }[],
      loadedMessage.content,
      loadedMessage.embeds,
    );
    if (disposition.requiresChoice) return { settledMessage: undefined, settledNotice: null };
    return {
      settledMessage: applyDisposition(loadedMessage),
      settledNotice: noticeMessageForSettled(disposition),
    };
  }, [loadedMessage]);
  const contentFloorError = settledMessage
    ? validateContentRequirements(settledMessage) : undefined;
  const isDisabled = isFetchingDiscordMessage || isFetchingCommandMessage || isLoadingWebhook;
  const guild = session?.user.guilds.find((g) => g.id === selectedGuildId);

  const menuRefs: Record<number, React.MutableRefObject<HTMLDivElement | null>> = {
    0: useRef<HTMLDivElement>(null),
    1: useRef<HTMLDivElement>(null),
  };

  const trpc = useQueryClient();
  const resetLoadMenu = useCallback(() => {
    trpc.removeQueries({ queryKey: getQueryKey(api.message.getFromUrl) });
    trpc.removeQueries({ queryKey: getQueryKey(api.message.getFromCode) });
    setMessageLink('');
    setCommandMessageCode('');
    setWebhookUrl('');
    setJsonMessage(null);
  }, [trpc]);

  const { labelProps, fieldProps } = useLabel({ label: 'Save To' });
  useEffect(() => { if (guild) setSelectedGuildId(guild.id); }, [guild]);

  const dropdownItems = useGuildDropdownItems({ setSelectedGuildId });

  const [pendingChoice, setPendingChoice] = useState<null | {
    options: readonly ContentLossOption[];
  }>(null);

  const submitData = useCallback((data: EditableMessageData) => {
    void upsertMessage({
      message: {
        data: saveAsPayload({ data }), name: messageName, guildId: selectedGuildId || null,
      },
    });
  }, [messageName, selectedGuildId]);

  const onSubmit = useCallback(() => {
    if (!loadedMessage) return;
    const gate = gateBeforePersist(settledMessage ?? loadedMessage);
    if (gate.mustAsk && gate.options) {
      setPendingChoice({ options: gate.options });
      return;
    }
    submitData(gate.data);
  }, [loadedMessage, settledMessage, submitData]);

  const commitChoice = useCallback((chosenOption: ContentLossOption) => {
    if (!loadedMessage) return;
    submitData(applyDisposition(loadedMessage, chosenOption.mode));
    setPendingChoice(null);
  }, [loadedMessage, submitData]);

  const cancelChoice = useCallback(() => setPendingChoice(null), []);

  const handleLoadOptionChange = useCallback<(option: LoadOption) => void>((option) => {
    setLoadOption(option);
    resetLoadMenu();
  }, [resetLoadMenu]);

  const messageErrorString = discordMessageError?.message
    ?? commandMessageError?.message
    ?? webhookError
    ?? webhookMessageError;
  const showPreview = isFetchingCommandMessage
    || isFetchingDiscordMessage
    || loadedMessage;
  const disableSave = !loadedMessage
    || !!contentFloorError
    || isSavingMessage
    || !messageName
    || messageName.length > MAX_MESSAGE_NAME_LENGTH;

  return (
    <PresetDialog
      open={open}
      title={pendingChoice ? 'Are you sure?' : 'Create or upload a new message'}
      onClose={pendingChoice ? cancelChoice : onClose}
      afterLeave={useCallback(() => {
        setPage(0);
        setLoadOption(session ? 'bot' : 'webhook');
        resetLoadMenu();
      }, [resetLoadMenu])}
      disableExternalClose={page > 0}
    >
      {pendingChoice ? (
        <>
          <p className="text-sm">
            This message has both Components V2 and classic content (text or embeds) — Discord
            cannot show both. Choose which to keep; nothing is created until you choose.
          </p>
          <div className={styles.flex({ col: true, gap: 2 })}>
            {pendingChoice.options.map((option) => (
              <Button
                key={option.mode}
                preset='tertiary'
                onPress={() => commitChoice(option)}
              >
                {option.mode === 'v2' ? 'Save as Components V2' : 'Save as Classic'}
                {' — '}
                {describeDropSet(option.dropSet)}
              </Button>
            ))}
          </div>
          <DialogFooter>
            <Button preset='hyperlink' onPress={cancelChoice}>
              Cancel
            </Button>
            <span />
          </DialogFooter>
        </>
      ) : (
        <TransitionHeightElement
          className="relative overflow-hidden"
          itemRef={menuRefs[page <= 0 ? 0 : page]}
        >
          <Transition
            as="div"
            ref={menuRefs[0]}
            show={page === 0}
            unmount={false}
            className="absolute w-full space-y-4"
            {...styles.transition({
              transition: 'transform ease-out',
              enter: 'duration-100',
              leave: 'duration-100',
              opened: 'translate-x-0',
              closed: '-translate-x-full',
            })}
          >
            <div>
              <StyledAccordion<LoadOption>
                onChange={handleLoadOptionChange}
                selected={loadOption}
                allowZeroExpanded={false}
                items={[
                  {
                    id: 'bot',
                    title: 'Message Link',
                    icon: <LinkIcon className='my-1 h-6 w-6' />,
                    children: (
                      <TextField
                        inputMode='url'
                        label='URL'
                        subLabel='Requires bot.'
                        tooltip='You can find this by right clicking a message and clicking "Copy Message Link". The bot will need the Read Messages permission for the channel.'
                        TooltipIcon={QuestionMarkCircleIcon}
                        value={messageIdOrUrl}
                        onChange={setMessageLink}
                        outerClassName='m-4 mt-3'
                        labelClassName='text-sm'
                        inputClassName='bg-input w-full shadow py-1 px-2 mt-2 rounded'
                        placeholder='https://discord.com/channels/...'
                        isDisabled={isDisabled}
                      />
                    ),
                  },
                  {
                    id: 'webhook',
                    title: 'Webhook',
                    icon: <WebhookIcon className='my-1 h-6 w-6' />,
                    children: (
                      <>
                        <TextField
                          inputMode='url'
                          label="Webhook URL"
                          tooltip='You can find this in the "Integrations" tab of your server settings.'
                          TooltipIcon={QuestionMarkCircleIcon}
                          value={webhookUrl}
                          onChange={setWebhookUrl}
                          outerClassName='m-4 mt-3'
                          labelClassName='flex flex-col text-sm'
                          inputClassName='bg-input w-full shadow py-1 px-2 mt-2 rounded'
                          placeholder='https://discord.com/api/webhooks/...'
                          isDisabled={isDisabled}
                        />
                        <TextField
                          inputMode='url'
                          label='Message Link or ID'
                          tooltip='You can find this by right clicking a message and clicking "Copy Message Link".'
                          TooltipIcon={QuestionMarkCircleIcon}
                          value={messageIdOrUrl}
                          onChange={setMessageLink}
                          outerClassName='m-4 mt-3'
                          labelClassName='flex flex-col text-sm'
                          inputClassName='bg-input w-full shadow py-1 px-2 mt-2 rounded'
                          placeholder='https://discord.com/channels/...'
                          isDisabled={isDisabled}
                        />
                      </>
                    ),
                  },
                  {
                    id: 'code',
                    title: 'Message Context Command',
                    icon: <ChatBubbleOvalLeftEllipsisIcon className='my-1 h-6 w-6' />,
                    children: (
                      <TextField
                        inputMode='text'
                        label='Code'
                        tooltip="You can get a code by accessing a message's context menu > Apps > Get Message"
                        TooltipIcon={QuestionMarkCircleIcon}
                        value={commandMessageCode}
                        onChange={setCommandMessageCode}
                        outerClassName='m-4 mt-3'
                        labelClassName='text-sm'
                        inputClassName='bg-input w-full shadow py-1 px-2 mt-2 rounded'
                        placeholder='dd536fb7e0aec46049f7b372f77aec...'
                        isDisabled={isDisabled}
                      />
                    ),
                  },
                  {
                    id: 'json',
                    title: 'JSON',
                    icon: <CodeBracketIcon className='my-1 h-6 w-6' />,
                    children: <NewMessageJsonInput setMessage={setJsonMessage} />,
                  },
                ]}
              />
              <NullableComponent show={messageErrorString}>
                <div className="mt-2 text-sm text-error">{messageErrorString}</div>
              </NullableComponent>
              <NullableComponent show={droppedComponentTypes.length > 0}>
                <div className="mt-2 text-sm text-error">
                  {describeDroppedComponentTypesNotice(droppedComponentTypes)}
                </div>
              </NullableComponent>
              <NullableComponent show={!!loadedMessage && contentFloorError}>
                <div className="mt-2 text-sm text-error">{contentFloorError}</div>
              </NullableComponent>
              <NullableComponent show={settledNotice}>
                <div className="mt-2 text-sm text-warning">{settledNotice}</div>
              </NullableComponent>
            </div>
            <NullableComponent show={showPreview}>
              <div className="rounded bg-tertiary p-4 pt-3">
                <h2 className="mb-2">Message Preview</h2>
                {loadedMessage ? (
                  <div className="rounded bg-primary p-2">
                    <MessagePreview
                      _key={page}
                      messageData={settledMessage ?? loadedMessage}
                      scale={0.5}
                    />
                  </div>
                ) : (
                  <div className={styles.flex({ cx: true })}>
                    <LoadingDots className={styles.largeIcon} />
                  </div>
                )}
              </div>
            </NullableComponent>
            <Button
              preset='success'
              onPress={() => setPage(1)}
              isDisabled={!loadedMessage || isDisabled}
              className='float-right'
            >
              Continue
              <ChevronRightIcon className={styles.icon} />
            </Button>
          </Transition>
          <Transition
            as="div"
            ref={menuRefs[1]}
            show={page === 1}
            unmount={false}
            className={classNames(styles.flex({ col: true, gap: 4 }), 'absolute w-full')}
            {...styles.transition({
              transition: 'transform ease-out',
              enter: 'duration-100',
              leave: 'duration-100',
              opened: 'translate-x-0',
              closed: 'translate-x-full',
            })}
          >
            <Form
              onSubmit={onSubmit}
              isDisabled={disableSave}
              className={styles.flex({ col: true, gap: 4 })}
            >
              <TextField
                inputMode='text'
                label='Message Name'
                subLabel={`${messageName.length} / ${MAX_MESSAGE_NAME_LENGTH}`}
                subLabelClassName={messageName.length > MAX_MESSAGE_NAME_LENGTH ? 'text-error' : undefined}
                value={messageName}
                onChange={setMessageName}
                labelClassName='text-sm'
                inputClassName='bg-input w-full shadow py-2 px-4 mt-2 rounded'
                placeholder='New Message'
                autoFocus
              />
              <div className={styles.flex({ col: true, gap: 1 })}>
                <div className="text-sm">
                  {/* eslint-disable-next-line jsx-a11y/label-has-associated-control */}
                  <label {...labelProps}>Save To</label>
                  <span className={styles.inlineSubLabel}>(max 50 per account / server)</span>
                </div>
                <Dropdown
                  portal
                  triggerClassName="p-2"
                  dropdownClassName='text-sm'
                  label={dropdownItems.find((item) => item.value === selectedGuildId)?.label ?? 'Select a Guild'}
                  items={dropdownItems}
                  maxItems={6}
                  {...fieldProps}
                />
              </div>
              <NullableComponent show={messageError}>
                <div className="whitespace-pre-line text-sm text-error">{formatMutationError(messageError)}</div>
              </NullableComponent>
            </Form>
            <DialogFooter>
              <Button
                preset='tertiary'
                onPress={() => setPage(0)}
                isDisabled={isSavingMessage}
              >
                <ChevronLeftIcon className={styles.icon} />
                Back
              </Button>
              <Button
                type="submit"
                preset='success'
                onPress={onSubmit}
                isDisabled={disableSave}
              >
                <CheckIcon className={styles.icon} />
                Save
              </Button>
            </DialogFooter>
          </Transition>
        </TransitionHeightElement>
      )}
    </PresetDialog>
  );
};

export default memo(NewMessageModal);
